59 // -------------------------------------------------------------------------------
63 // -------------------------------------------------------------------------------
64 typedef enum aiMetadataType {
65     AI_BOOL = 0,
66     AI_INT32 = 1,
67     AI_UINT64 = 2,
68     AI_FLOAT = 3,
69     AI_DOUBLE = 4,
70     AI_AISTRING = 5,
71     AI_AIVECTOR3D = 6,
72     AI_AIMETADATA = 7,
73     AI_META_MAX = 8,
74 
75 #ifndef SWIG
76     FORCE_32BIT = INT_MAX
77 #endif
78 } aiMetadataType;
79 
80 // -------------------------------------------------------------------------------
86 // -------------------------------------------------------------------------------
87 struct aiMetadataEntry {
88     aiMetadataType mType;
89     void *mData;
90 
91 #ifdef __cplusplus
92     aiMetadataEntry() :
93             mType(AI_META_MAX),
94             mData( nullptr ) {
95         // empty
96     }
97 #endif
98 };
99 
100 #ifdef __cplusplus
101 
102 #include <string>
103 
104 struct aiMetadata;
105 
106 // -------------------------------------------------------------------------------
110 // -------------------------------------------------------------------------------
111 
112 inline aiMetadataType GetAiType(bool) {
113     return AI_BOOL;
114 }
115 inline aiMetadataType GetAiType(int32_t) {
116     return AI_INT32;
117 }
118 inline aiMetadataType GetAiType(uint64_t) {
119     return AI_UINT64;
120 }
121 inline aiMetadataType GetAiType(float) {
122     return AI_FLOAT;
123 }
124 inline aiMetadataType GetAiType(double) {
125     return AI_DOUBLE;
126 }
127 inline aiMetadataType GetAiType(const aiString &) {
128     return AI_AISTRING;
129 }
130 inline aiMetadataType GetAiType(const aiVector3D &) {
131     return AI_AIVECTOR3D;
132 }
133 inline aiMetadataType GetAiType(const aiMetadata &) {
134     return AI_AIMETADATA;
135 }
136 
137 #endif // __cplusplus
138 
139 // -------------------------------------------------------------------------------
145 // -------------------------------------------------------------------------------
146 struct aiMetadata {
148     unsigned int mNumProperties;
149 
151     C_STRUCT aiString *mKeys;
152 
155     C_STRUCT aiMetadataEntry *mValues;
156 
157 #ifdef __cplusplus
158 
162     aiMetadata() AI_NO_EXCEPT
163             : mNumProperties(0),
164               mKeys(nullptr),
165               mValues(nullptr) {
166         // empty
167     }
168 
169     aiMetadata(const aiMetadata &rhs) :
170             mNumProperties(rhs.mNumProperties), mKeys(nullptr), mValues(nullptr) {
171         mKeys = new aiString[mNumProperties];
172         for (size_t i = 0; i < static_cast<size_t>(mNumProperties); ++i) {
173             mKeys[i] = rhs.mKeys[i];
174         }
175         mValues = new aiMetadataEntry[mNumProperties];
176         for (size_t i = 0; i < static_cast<size_t>(mNumProperties); ++i) {
177             mValues[i].mType = rhs.mValues[i].mType;
178             switch (rhs.mValues[i].mType) {
179             case AI_BOOL:
180                 mValues[i].mData = new bool;
181                 ::memcpy(mValues[i].mData, rhs.mValues[i].mData, sizeof(bool));
182                 break;
183             case AI_INT32: {
184                 int32_t v;
185                 ::memcpy(&v, rhs.mValues[i].mData, sizeof(int32_t));
186                 mValues[i].mData = new int32_t(v);
187             } break;
188             case AI_UINT64: {
189                 uint64_t v;
190                 ::memcpy(&v, rhs.mValues[i].mData, sizeof(uint64_t));
191                 mValues[i].mData = new uint64_t(v);
192             } break;
193             case AI_FLOAT: {
194                 float v;
195                 ::memcpy(&v, rhs.mValues[i].mData, sizeof(float));
196                 mValues[i].mData = new float(v);
197             } break;
198             case AI_DOUBLE: {
199                 double v;
200                 ::memcpy(&v, rhs.mValues[i].mData, sizeof(double));
201                 mValues[i].mData = new double(v);
202             } break;
203             case AI_AISTRING: {
204                 aiString v;
205                 rhs.Get<aiString>(static_cast<unsigned int>(i), v);
206                 mValues[i].mData = new aiString(v);
207             } break;
208             case AI_AIVECTOR3D: {
209                 aiVector3D v;
210                 rhs.Get<aiVector3D>(static_cast<unsigned int>(i), v);
211                 mValues[i].mData = new aiVector3D(v);
212             } break;
213             case AI_AIMETADATA: {
214                 aiMetadata v;
215                 rhs.Get<aiMetadata>(static_cast<unsigned int>(i), v);
216                 mValues[i].mData = new aiMetadata(v);
217             } break;
218 #ifndef SWIG
219             case FORCE_32BIT:
220 #endif
221             default:
222                 break;
223             }
224         }
225     }
226 
227     aiMetadata &operator=(aiMetadata rhs) {
228         using std::swap;
229         swap(mNumProperties, rhs.mNumProperties);
230         swap(mKeys, rhs.mKeys);
231         swap(mValues, rhs.mValues);
232         return *this;
233     }
234 
238     ~aiMetadata() {
239         delete[] mKeys;
240         mKeys = nullptr;
241         if (mValues) {
242             // Delete each metadata entry
243             for (unsigned i = 0; i < mNumProperties; ++i) {
244                 void *data = mValues[i].mData;
245                 switch (mValues[i].mType) {
246                 case AI_BOOL:
247                     delete static_cast<bool *>(data);
248                     break;
249                 case AI_INT32:
250                     delete static_cast<int32_t *>(data);
251                     break;
252                 case AI_UINT64:
253                     delete static_cast<uint64_t *>(data);
254                     break;
255                 case AI_FLOAT:
256                     delete static_cast<float *>(data);
257                     break;
258                 case AI_DOUBLE:
259                     delete static_cast<double *>(data);
260                     break;
261                 case AI_AISTRING:
262                     delete static_cast<aiString *>(data);
263                     break;
264                 case AI_AIVECTOR3D:
265                     delete static_cast<aiVector3D *>(data);
266                     break;
267                 case AI_AIMETADATA:
268                     delete static_cast<aiMetadata *>(data);
269                     break;
270 #ifndef SWIG
271                 case FORCE_32BIT:
272 #endif
273                 default:
274                     break;
275                 }
276             }
277 
278             // Delete the metadata array
279             delete[] mValues;
280             mValues = nullptr;
281         }
282     }
283 
288     static inline aiMetadata *Alloc(unsigned int numProperties) {
289         if (0 == numProperties) {
290             return nullptr;
291         }
292 
293         aiMetadata *data = new aiMetadata;
294         data->mNumProperties = numProperties;
295         data->mKeys = new aiString[data->mNumProperties]();
296         data->mValues = new aiMetadataEntry[data->mNumProperties]();
297 
298         return data;
299     }
300 
304     static inline void Dealloc(aiMetadata *metadata) {
305         delete metadata;
306     }
307 
308     template <typename T>
309     inline void Add(const std::string &key, const T &value) {
310         aiString *new_keys = new aiString[mNumProperties + 1];
311         aiMetadataEntry *new_values = new aiMetadataEntry[mNumProperties + 1];
312 
313         for (unsigned int i = 0; i < mNumProperties; ++i) {
314             new_keys[i] = mKeys[i];
315             new_values[i] = mValues[i];
316         }
317 
318         delete[] mKeys;
319         delete[] mValues;
320 
321         mKeys = new_keys;
322         mValues = new_values;
323 
324         mNumProperties++;
325 
326         Set(mNumProperties - 1, key, value);
327     }
328 
329     template <typename T>
330     inline bool Set(unsigned index, const std::string &key, const T &value) {
331         // In range assertion
332         if (index >= mNumProperties) {
333             return false;
334         }
335 
336         // Ensure that we have a valid key.
337         if (key.empty()) {
338             return false;
339         }
340 
341         // Set metadata key
342         mKeys[index] = key;
343 
344         // Set metadata type
345         mValues[index].mType = GetAiType(value);
346 
347         // Copy the given value to the dynamic storage
348         if (nullptr != mValues[index].mData && AI_AIMETADATA != mValues[index].mType) {
349             ::memcpy(mValues[index].mData, &value, sizeof(T));
350         } else if (nullptr != mValues[index].mData && AI_AIMETADATA == mValues[index].mType) {
351             *static_cast<T *>(mValues[index].mData) = value;
352         } else {
353             if (nullptr != mValues[index].mData) {
354                 delete static_cast<T *>(mValues[index].mData);
355                 mValues[index].mData = nullptr;
356             }
357             mValues[index].mData = new T(value);
358         }
359 
360         return true;
361     }
362 
363     template <typename T>
364     inline bool Set(const std::string &key, const T &value) {
365         if (key.empty()) {
366             return false;
367         }
368 
369         bool result = false;
370         for (unsigned int i = 0; i < mNumProperties; ++i) {
371             if (key == mKeys[i].C_Str()) {
372                 Set(i, key, value);
373                 result = true;
374                 break;
375             }
376         }
377 
378         return result;
379     }
380 
381     template <typename T>
382     inline bool Get(unsigned index, T &value) const {
383         // In range assertion
384         if (index >= mNumProperties) {
385             return false;
386         }
387 
388         // Return false if the output data type does
389         // not match the found value's data type
390         if (GetAiType(value) != mValues[index].mType) {
391             return false;
392         }
393 
394         // Otherwise, output the found value and
395         // return true
396         value = *static_cast<T *>(mValues[index].mData);
397 
398         return true;
399     }
400 
401     template <typename T>
402     inline bool Get(const aiString &key, T &value) const {
403         // Search for the given key
404         for (unsigned int i = 0; i < mNumProperties; ++i) {
405             if (mKeys[i] == key) {
406                 return Get(i, value);
407             }
408         }
409         return false;
410     }
411 
412     template <typename T>
413     inline bool Get(const std::string &key, T &value) const {
414         return Get(aiString(key), value);
415     }
416 
422     inline bool Get(size_t index, const aiString *&key, const aiMetadataEntry *&entry) const {
423         if (index >= mNumProperties) {
424             return false;
425         }
426 
427         key = &mKeys[index];
428         entry = &mValues[index];
429 
430         return true;
431     }
432 
435     inline bool HasKey(const char *key) const {
436         if (nullptr == key) {
437             return false;
438         }
439 
440         // Search for the given key
441         for (unsigned int i = 0; i < mNumProperties; ++i) {
442             if (0 == strncmp(mKeys[i].C_Str(), key, mKeys[i].length)) {
443                 return true;
444             }
445         }
446         return false;
447     }
448 
449     friend bool CompareKeys(const aiMetadata &lhs, const aiMetadata &rhs) {
450         if (lhs.mNumProperties != rhs.mNumProperties) {
451             return false;
452         }
453 
454         for (unsigned int i = 0; i < lhs.mNumProperties; ++i) {
455             if (lhs.mKeys[i] != rhs.mKeys[i]) {
456                 return false;
457             }
458         }
459         return true;
460     }
461 
462     friend bool CompareValues(const aiMetadata &lhs, const aiMetadata &rhs) {
463         if (lhs.mNumProperties != rhs.mNumProperties) {
464             return false;
465         }
466 
467         for (unsigned int i = 0; i < lhs.mNumProperties; ++i) {
468             if (lhs.mValues[i].mType != rhs.mValues[i].mType) {
469                 return false;
470             }
471 
472             switch (lhs.mValues[i].mType) {
473             case AI_BOOL: {
474                 if (*static_cast<bool *>(lhs.mValues[i].mData) != *static_cast<bool *>(rhs.mValues[i].mData)) {
475                     return false;
476                 }
477             } break;
478             case AI_INT32: {
479                 if (*static_cast<int32_t *>(lhs.mValues[i].mData) != *static_cast<int32_t *>(rhs.mValues[i].mData)) {
480                     return false;
481                 }
482             } break;
483             case AI_UINT64: {
484                 if (*static_cast<uint64_t *>(lhs.mValues[i].mData) != *static_cast<uint64_t *>(rhs.mValues[i].mData)) {
485                     return false;
486                 }
487             } break;
488             case AI_FLOAT: {
489                 if (*static_cast<float *>(lhs.mValues[i].mData) != *static_cast<float *>(rhs.mValues[i].mData)) {
490                     return false;
491                 }
492             } break;
493             case AI_DOUBLE: {
494                 if (*static_cast<double *>(lhs.mValues[i].mData) != *static_cast<double *>(rhs.mValues[i].mData)) {
495                     return false;
496                 }
497             } break;
498             case AI_AISTRING: {
499                 if (*static_cast<aiString *>(lhs.mValues[i].mData) != *static_cast<aiString *>(rhs.mValues[i].mData)) {
500                     return false;
501                 }
502             } break;
503             case AI_AIVECTOR3D: {
504                 if (*static_cast<aiVector3D *>(lhs.mValues[i].mData) != *static_cast<aiVector3D *>(rhs.mValues[i].mData)) {
505                     return false;
506                 }
507             } break;
508             case AI_AIMETADATA: {
509                 if (*static_cast<aiMetadata *>(lhs.mValues[i].mData) != *static_cast<aiMetadata *>(rhs.mValues[i].mData)) {
510                     return false;
511                 }
512             } break;
513 #ifndef SWIG
514             case FORCE_32BIT:
515 #endif
516             default:
517                 break;
518             }
519         }
520 
521         return true;
522     }
523 
524     friend bool operator==(const aiMetadata &lhs, const aiMetadata &rhs) {
525         return CompareKeys(lhs, rhs) && CompareValues(lhs, rhs);
526     }
527 
528     friend bool operator!=(const aiMetadata &lhs, const aiMetadata &rhs) {
529         return !(lhs == rhs);
530     }
531 
532 #endif // __cplusplus
533 };
534 
535 #endif // AI_METADATA_H_INC
